"""Alembic 마이그레이션 검증.

테스트 DB는 conftest에서 `upgrade head`로 만들어지므로, 여기서는
모델과의 일치 여부와 되돌리기(downgrade) 가능 여부를 확인한다.
"""
from alembic import command
from alembic.script import ScriptDirectory

from conftest import alembic_config


def test_single_head():
    # 브랜치가 갈라져 head가 여러 개면 upgrade head가 실패하므로 하나여야 함
    heads = ScriptDirectory.from_config(alembic_config()).get_heads()

    assert len(heads) == 1, f"Alembic head가 여러 개입니다: {heads}"


def test_migrations_match_models():
    # 모델을 바꾸고 마이그레이션을 만들지 않았으면 실패 (AutogenerateDiffsDetected)
    command.check(alembic_config())


def test_downgrade_and_upgrade_roundtrip():
    cfg = alembic_config()

    command.downgrade(cfg, "base")
    command.upgrade(cfg, "head")
    command.check(cfg)
